mapper.select:
SELECT DSTAFF.ID, DBED.ID BED_ID, nvl( ROOM.ALIAS_NAME, ROOM.ROOM_NAME ) AS ROOM_NAME, DBED.BED_NUMBER, DSTAFF.STAFF_BADGE, ROOM.ROOM_SEX, DBED.BED_NAME, DBED.ROOM_ID, STAFF.PQCOMPANY, DSTAFF.STAFF_NAME, DSTAFF.STAFF_SEX, STAFF.COMP_NAME, STAFF.DEP_NAME, STAFF.JCHE_NAME, STAFF.JOB_NAME, DSTAFF.comp_name AS dor_comp_name, DSTAFF.dep_name AS dor_dep_name, DSTAFF.job_name AS dor_job_name, STAFF.STATUS, room.room_type AS dormitory_type_id, DBED.DORMITORY_ID, DBED.DEL_FLAG, STAFF.DEP_ABBR, DSTAFF.SIMPLE_REMARK, DSTAFF.CREATE_TIME, DBED.PARK_ID, STAFF.RESIDENTADDRESS, STAFF.CERTNO, STAFF.LEA_DATE, STAFF.LEA_TYPE, STAFF.NATION, STAFF.PHONE FROM SMT_DORMITORY_BED DBED LEFT JOIN SMT_DORMITORY_STAFF DSTAFF ON ( DSTAFF.PARK_ID = DBED.PARK_ID AND DSTAFF.FLOOR_ID = DBED.FLOOR_ID AND DSTAFF.ROOM_ID = DBED.ROOM_ID AND DSTAFF.DORMITORY_ID = DBED.DORMITORY_ID AND DSTAFF.BED_ID = DBED.ID ) LEFT JOIN SMT_STAFF STAFF ON DSTAFF.STAFF_BADGE = STAFF.BADGE LEFT JOIN SMT_DORMITORY_ROOM ROOM ON ROOM.ID = DBED.ROOM_ID
and DSTAFF.staff_badge LIKE CONCAT(CONCAT('%',#{query.staffBadge}),'%')
AND DBED.PARK_ID=#{query.parkId }
AND DBED.DORMITORY_ID=#{query.dormitoryId}
and DBED.DORMITORY_ID in
#{item}
AND DBED.FLOOR_ID =#{query.floorId }
AND DBED.ROOM_ID =#{query.roomId }
and (DSTAFF.comp_name LIKE CONCAT(CONCAT('%',#{query.compName}),'%') or STAFF.comp_name LIKE CONCAT(CONCAT('%',#{query.compName}),'%') )
AND DSTAFF.STAFF_NAME LIKE CONCAT(CONCAT('%',#{query.name}),'%')
AND STAFF.PQCOMPANY LIKE CONCAT(CONCAT('%',#{query.pqcompany}),'%')
AND STAFF.STATUS =#{query.status}
AND DSTAFF.STAFF_BADGE LIKE CONCAT(CONCAT('%',#{query.staffBadge}),'%')
AND DSTAFF.STAFF_BADGE is null
AND DSTAFF.STAFF_BADGE is not null
AND room.room_type =#{query.roomType}
and DBED.PARK_ID in
#{item}
AND DSTAFF.CREATE_TIME between to_date(#{query.startTime},'yyyy-mm-dd hh24:mi:ss') and to_date(#{query.endTime},'yyyy-mm-dd hh24:mi:ss')
AND STAFF.PHONE LIKE CONCAT(CONCAT('%',#{query.phone}),'%')
ORDER BY ROOM_NAME ,BED_NUMBER, CASE WHEN STAFF.BADGE IS NULL THEN 1 ELSE 0 END ASC, DSTAFF.CREATE_TIME DESC

SELECT DSTAFF.ID, DBED.ID BED_ID,nvl(ROOM.ALIAS_NAME,ROOM.ROOM_NAME) ROOM_NAME,DBED.BED_NUMBER,DSTAFF.STAFF_BADGE, ROOM.ROOM_SEX,DBED.BED_NAME,DBED.ROOM_ID, DSTAFF.STAFF_NAME name, DSTAFF.STAFF_SEX,STAFF.COMP_NAME, STAFF.DEP_NAME,STAFF.JCHE_NAME ,STAFF.JOB_NAME, DSTAFF.comp_name as dor_comp_name ,DSTAFF.dep_name as dor_dep_name,DSTAFF.job_name as dor_job_name, STAFF.STATUS,ty.type_name,lev.JCHE_ID,DORMITORY.DORMITORY_NAME,DBED.DEL_FLAG,STAFF.DEP_ABBR, DSTAFF.CREATE_TIME ,PARK.PARK_NAME,STAFF.RESIDENTADDRESS, STAFF.CERTNO, STAFF.LEA_DATE,STAFF.LEA_TYPE,STAFF.NATION,STAFF.PHONE, F.NAME FAMILY_NAME, F.BADGE FAMILY_BADGE, F.CERTNO FAMILY_CERTNO, F.PHONE FAMILY_PHONE, F.RELATION FAMILY_RELATION FROM SMT_DORMITORY_BED DBED LEFT JOIN SMT_DORMITORY_STAFF DSTAFF ON (DSTAFF.PARK_ID=DBED.PARK_ID AND DSTAFF.FLOOR_ID=DBED.FLOOR_ID AND DSTAFF.ROOM_ID=DBED.ROOM_ID AND DSTAFF.DORMITORY_ID=DBED.DORMITORY_ID AND DSTAFF.BED_ID=DBED.ID) LEFT JOIN SMT_STAFF STAFF ON DSTAFF.STAFF_BADGE = STAFF.BADGE LEFT JOIN SMT_DORMITORY_ROOM ROOM ON ROOM.ID=DBED.ROOM_ID RIGHT JOIN SMT_STAFF_FAMILY_DORMITORY F ON F.STAFF_BADGE = DSTAFF.STAFF_BADGE left join smt_dormitory_type ty on ty.id=room.room_type LEFT JOIN SMT_DORMITORY_LEVEL lev on lev.DORMITORY_TYPE_ID=room.room_type LEFT JOIN SMT_PARK PARK on DBED.PARK_ID=PARK.ID LEFT JOIN SMT_DORMITORY DORMITORY on DBED.DORMITORY_ID = DORMITORY.ID
F.DEL_FLAG = 0
and DSTAFF.staff_badge LIKE CONCAT(CONCAT('%',#{query.staffBadge}),'%')
AND DBED.PARK_ID=#{query.parkId }
AND DBED.DORMITORY_ID=#{query.dormitoryId}
AND DBED.FLOOR_ID =#{query.floorId }
AND DBED.ROOM_ID =#{query.roomId }
and (DSTAFF.comp_name LIKE CONCAT(CONCAT('%',#{query.compName}),'%') or STAFF.comp_name LIKE CONCAT(CONCAT('%',#{query.compName}),'%') )
AND DSTAFF.STAFF_NAME LIKE CONCAT(CONCAT('%',#{query.name}),'%')
AND STAFF.STATUS =#{query.status }
AND DSTAFF.STAFF_BADGE LIKE CONCAT(CONCAT('%',#{query.staffBadge}),'%')
AND DSTAFF.STAFF_BADGE is null
AND DSTAFF.STAFF_BADGE is not null
AND room.room_type =#{query.roomType}
and DBED.PARK_ID in
#{item}
AND DSTAFF.CREATE_TIME between to_date(#{query.startTime},'yyyy-mm-dd hh24:mi:ss') and to_date(#{query.endTime},'yyyy-mm-dd hh24:mi:ss')
AND STAFF.PHONE LIKE CONCAT(CONCAT('%',#{query.phone}),'%')
ORDER BY CASE WHEN STAFF.BADGE IS NULL THEN 1 ELSE 0 END, ROOM_NAME ,BED_NUMBER ASC, DSTAFF.CREATE_TIME DESC

select count(1) from SMT_DORMITORY_STAFF DSTAFF
inner join SMT_STAFF STAFF ON DSTAFF.STAFF_BADGE = STAFF.BADGE
where STAFF.status=0


	AND DSTAFF.PARK_ID=#{query.parkId }


	AND DSTAFF.DORMITORY_ID=#{query.dormitoryId}


	and DSTAFF.DORMITORY_ID in

		#{item}



	AND DSTAFF.FLOOR_ID =#{query.floorId }


	AND DSTAFF.ROOM_ID =#{query.roomId }

SELECT count(*) FROM SMT_DORMITORY_BED bed


		and PARK_ID =#{parkId }


	and not exists (select 1 from SMT_DORMITORY_STAFF df where df.BED_ID=bed.ID)

mapper.delete:
DELETE FROM SMT_DORMITORY_BED sdb WHERE ID IN

	#{item}

and not EXISTS (select 1 from SMT_DORMITORY_STAFF sds where sdb.ID=sds.BED_ID)
